import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Usf Panel — Gestor VLESS","description":"Panel premium de túneles VLESS y suscripciones: multiusuario, sincronización Clash/v2ray/sing-box, despliegue con un comando en HF, Railway, Render, Fly y Koyeb.","frontmatter":{"title":"Usf Panel — Gestor VLESS","description":"Panel premium de túneles VLESS y suscripciones: multiusuario, sincronización Clash/v2ray/sing-box, despliegue con un comando en HF, Railway, Render, Fly y Koyeb."},"headers":[],"relativePath":"es/projects/usf-panel/index.md","filePath":"es/projects/usf-panel/index.md"}`),a={name:`es/projects/usf-panel/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="usf-panel-—-gestor-vless" tabindex="-1">Usf Panel — Gestor VLESS <a class="header-anchor" href="#usf-panel-—-gestor-vless" aria-label="Permalink to “Usf Panel — Gestor VLESS”">​</a></h1><p><strong>Usf Panel</strong> es el buque insignia de mi trabajo de redes: un <strong>gestor premium de túneles VLESS y suscripciones</strong> construido como una aplicación FastAPI de un solo archivo. Gestiona acceso multiusuario, genera enlaces de suscripción que Clash, v2ray y sing-box consumen nativamente, y se despliega en cinco plataformas con un comando cada una.</p><h2 id="por-que-otro-panel" tabindex="-1">Por qué otro panel <a class="header-anchor" href="#por-que-otro-panel" aria-label="Permalink to “Por qué otro panel”">​</a></h2><p>Los paneles existentes son o pesados de nivel empresarial (una granja de servidores para correr un túnel) o de calidad de juguete (sin gestión de usuarios, sin estadísticas, sin resiliencia). Usf Panel se toma en serio el camino intermedio: un archivo Python que puedes leer, un panel admin real con token + 2FA, contabilidad de tráfico por usuario, y objetivos de despliegue que siguen cómo evoluciona realmente la censura — cuando una plataforma se vuelve agresiva, te mudas en minutos, no días.</p><table tabindex="0"><thead><tr><th>Capacidad</th><th>Detalle</th></tr></thead><tbody><tr><td>Protocolos</td><td>VLESS sobre WS/TLS, configs listos para Reality.</td></tr><tr><td>Suscripciones</td><td>Enlaces auto-generados; compatibles con Clash / v2ray / sing-box.</td></tr><tr><td>Usuarios</td><td>Multiusuario con cuotas, expiración y estadísticas de tráfico.</td></tr><tr><td>Admin</td><td>Panel endurecido con token + 2FA y registro de auditoría.</td></tr><tr><td>Despliegue</td><td>Hugging Face · Railway · Render · Fly.io · Koyeb — un comando cada uno.</td></tr></tbody></table><h2 id="la-familia" tabindex="-1">La familia <a class="header-anchor" href="#la-familia" aria-label="Permalink to “La familia”">​</a></h2><p>Usf Panel no está solo — es el centro de una familia que cubre cada filosofía de alojamiento: <strong>usf-edge</strong> corre la misma idea enteramente en Cloudflare Workers con estado KV en más de 300 PoPs; <strong>edge-pp</strong> extiende edgetunnel con un panel completo de gestión de usuarios; <strong>Render-usf</strong> apunta a Render con medidas antibloqueo; <strong>Usf-Pnl-pro</strong> empaqueta el despliegue multiplataforma. La sección de <a href="/Usf/es/about/networking/">redes</a> explica por qué la redundancia entre plataformas es un requisito de diseño, no una opción.</p><div class="warning custom-block"><p class="custom-block-title">Nota de responsabilidad</p><p>Estas herramientas existen para restaurar el acceso a la información, no para entrar en nada. Se publican endurecidas — no con exploits — y espero que los usuarios respeten las leyes de sus propias jurisdicciones.</p></div>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};